"""Strict-flow capital-flow hybrid for Kaggriculture -- vendored, not ours.

Source: Kaito Fukami, "141/200 Post-Freeze Top-100 | v54 Strict Flow", a public
Kaggle notebook for this competition.
https://www.kaggle.com/code/kaitofukami/141-200-post-freeze-top-100-v54-strict-flow
Last run 2026-08-30; extracted and vendored here 2026-08-31.

Like the earlier vendored kernels this one ships its agent base85-encoded,
zlib-compressed and SHA-256 checked rather than as readable source. This file
is that blob decoded. The decoded body is 171,508 bytes and hashes to
9f21735aaf0354e064e1d9bab1b2e186fad12cf6446e7ecf83f5014915e04a4f, the checksum
the notebook itself asserts; the digest was re-derived from the notebook's own
payload string rather than taken on trust, and again from this file before it
was committed. Nothing below this docstring is our work.

**This copy is byte-verbatim, which the other vendored kernels are not.** They
are formatted and import-sorted like the rest of the tree, on the reasoning
that provenance is established by diffing our copy against the cached kernel.
That reasoning does not survive an agent this size: the body is 1,972 lines of
which 1,600 are payload string, no cached runnable of it exists in this repo to
diff against, and the only thing that can establish provenance is the notebook's
own digest -- which only means something if the bytes we hash are the bytes we
run. So the file is excluded from `ruff format` (`.pre-commit-config.yaml`)
rather than from `ruff check`, and `tests/test_vendored_policies.py` recomputes
the digest over everything from the author's docstring to the end of the file.
Reformatting it would not change how it plays; it would change what the header
above can be checked against, which is the whole point of the header.

Two consequences of vendoring it whole rather than trimming it:

* The file carries two module docstrings. The author's own -- "v51:
  current-meta capital-flow hybrid" -- opens the body and is left where it is,
  because it is inside the hashed region. The earlier vendors folded the
  author's docstring into ours; that edit is exactly what is not available
  here.
* **Importing this module injects modules into `sys.modules`.** The body
  decodes and `exec`s a bundled ancestor at import time, which registers
  `_v50_frozen_v49`, `_v51_frozen_v50`, `v19_terminal`, `v23`, `v24`, `v44`,
  `v48`, `v49`, `v50` and -- the one that matters -- a top-level `scripts`.
  None of those is a module in the `kaggriculture` package, which is only ever
  imported dotted (`kaggriculture.scripts`, `kaggriculture.search.scripts`), so
  nothing here is shadowed. The repository's own top-level `scripts/` directory
  is a namespace package that no module imports and that the submission archive
  does not contain. The import costs 0.5 s, once, out of the 60 s overage pool.

Gate evidence, held-out seeds 700000-700063 played in both seat orderings
(128 games per opponent), engine kaggle-environments 1.32.7:

    vs boatlee_v14 (what we served)   64/64 = 1.000   [0.943, 1.000]
    pooled public frontier            226/256 = 0.883  lower 0.838 (bar 0.45)
    vs kaito v48                      48/64 = 0.750    [0.632, 0.840]

v48 is the same author's previous kernel, gated here two days earlier and never
served; v54 banks a mean of 88,054 against its 81,074. Both frontier-hardened
conditions -- beat the served agent, and hold up against a pool of fresh
top-band tapes rather than against history -- pass by wide margins, which is
the bar the 2026-08-20 serve failure put in place.

Left unlinted and untyped for the same reason `kaito_policy.py` is: annotating
functions nobody here has read would mean writing down types we have not
checked. Its behaviour is pinned by `tests/test_vendored_policies.py`, which
also pins the digest above.
"""

