_V54_CONFIG = _V51ResidualConfig(**{'front_existing_sells': True, 'front_on_near': False, 'front_money_deficit': 1000000.0, 'front_supply_threshold': 3.0, 'preempt_enabled': True, 'preempt_on_near': False, 'preempt_horizon': 2, 'preempt_maximum_batch': 4, 'near_scheduled_supply_weight': 0.0, 'adaptive_near_schedule_weight': True, 'adaptive_confidence_decay': 0.99, 'adaptive_confidence_negative_alpha': 0.55, 'adaptive_confidence_minimum_events': 2, 'adaptive_confidence_activation_threshold': 0.3, 'preempt_money_deficit': 1000000.0, 'near_distance': 8.0, 'near_streak_required': 12})
_V51_POLICY = _v51_build_policy(_V54_ROUTE, _V54_CONFIG)

# Keep the deployed controller runtime-blind to the engine random seed.  The
# validation harness already supplies this same redacted configuration.
_V54_INNER_AGENT = agent
def agent(obs, configuration=None):
    visible = configuration
    if isinstance(configuration, dict):
        visible = {
            key: value
            for key, value in configuration.items()
            if str(key).lower() not in {"seed", "randomseed"}
        }
    return _V54_INNER_AGENT(obs, visible)
